{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Azure SQL Database is not zone redundant",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database explicitly sets zone_redundant to false, reducing resilience to availability-zone failures."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = true\n}\n",
  "fix_summary": "Enabled zone redundancy for the Azure SQL database to improve availability during zone-level failures."
}
